    },
    {
      "id": "E2d81a6a16a58e987",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O guia de inspeção trata a cibersegurança de IACS com abordagem proporcional e direcionada, aplicável a instalações reguladas NIS e não NIS, por meio de categorias de inspeção distintas.",
          "trechos": [
            "E2d81a6a16a58e987:0:698",
            "E2d81a6a16a58e987:698:1391",
            "E2d81a6a16a58e987:1391:2091"
          ],
          "condicoes": [
            "aplica-se ao contexto regulatório do UKCS e às inspeções do OSDR/HSE",
            "refere-se a inspeções iniciais e subsequentes de cibersegurança"
          ],
          "limites": [
            "o trecho não detalha inventário, zonas, conduítes, DMZ nem regras de firewall",
            "é orientação regulatória estrangeira, não requisito brasileiro"
          ]
        },
        {
          "proposicao": "O objetivo principal da inspeção é verificar a adequação do sistema de gestão de cibersegurança de IACS, incluindo gestão de competências e eficácia de contramedidas.",
          "trechos": [
            "E2d81a6a16a58e987:1391:2091",
            "E2d81a6a16a58e987:2091:2518"
          ],
          "condicoes": [
            "voltado a locais com potencial de acidentes maiores e operadores de serviços essenciais cobertos pelo regulamento citado"
          ],
          "limites": [
            "o trecho não explicita critérios técnicos de segmentação de redes",
            "a verificação é por inspeção de adequação, não demonstração de desempenho universal"
          ]
        },
        {
          "proposicao": "A definição de IACS no guia abrange sistemas básicos de controle de processo e equipamentos sob controle ou com funções de camada independente de proteção.",
          "trechos": [
            "E2d81a6a16a58e987:2091:2518"
          ],
          "condicoes": [
            "no contexto do guia de inspeção de cibersegurança do HSE"
          ],
          "limites": [
            "o recorte funcional é parcial no trecho disponível",
            "não há fronteira explícita entre IT e OT nem decomposição em zonas"
          ]
        }
      ]
    },
    {
      "id": "E68ff9b835100fc73",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A segurança funcional é apresentada como parte de um conjunto de medidas para minimizar risco e prevenir eventos perigosos, e sua inspeção busca consistência com a BS EN 61511.",
          "trechos": [
            "E68ff9b835100fc73:0:699"
          ],
          "condicoes": [
            "no contexto de inspeção de segurança funcional offshore"
          ],
          "limites": [
            "o foco principal é segurança funcional, não arquitetura IT/OT",
            "a referência normativa é estrangeira e não deve ser tratada como requisito brasileiro"
          ]
        },
        {
          "proposicao": "A implementação robusta de segurança funcional é relacionada a elementos operacionais como limites operacionais seguros, gestão de alarmes, sobreposições/inibições e outras medidas de prevenção.",
          "trechos": [
            "E68ff9b835100fc73:699:1396"
          ],
          "condicoes": [
            "como componentes de projeto e operação avaliados em inspeção"
          ],
          "limites": [
            "não há descrição de inventário, segmentação em zonas/conduítes, DMZ ou firewalls",
            "a relação com cibersegurança é indireta"
          ]
        },
        {
          "proposicao": "O próprio guia remete a um guia específico de cibersegurança de IACS para inspeção da gestão de riscos cibernéticos, indicando interface entre segurança funcional e cibersegurança.",
          "trechos": [
            "E68ff9b835100fc73:1396:2085"
          ],
          "condicoes": [
            "quando a avaliação envolver risco cibernético em IACS"
          ],
          "limites": [
            "não detalha como implementar defesa em profundidade ou segregação de redes",
            "é indicação de interface documental, não critério técnico completo"
          ]
        }
      ]
    },
    {
      "id": "E17bd6f60d466f9f9",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O alerta relata vulnerabilidades em ICS que poderiam permitir a um atacante remoto altamente qualificado assumir controle de sistemas industriais como válvulas e controle de vazão e pressão.",
          "trechos": [
            "E17bd6f60d466f9f9:0:697"
          ],
          "condicoes": [
            "no contexto das vulnerabilidades citadas pela CISA para implementações Treck TCP/IP",
            "dependente da exposição dos sistemas afetados"
          ],
          "limites": [
            "trata de um conjunto específico de vulnerabilidades, não de toda arquitetura IT/OT",
            "não quantifica probabilidade nem impacto para FPSOs"
          ]
        },
        {
          "proposicao": "O documento recomenda avaliar exposição, mitigar riscos, acionar fornecedores para patches e estratégias de remediação e atualizar versões estáveis quando aplicável.",
          "trechos": [
            "E17bd6f60d466f9f9:697:1390"
          ],
          "condicoes": [
            "condicionado à presença de produtos e implementações afetados",
            "dependente de disponibilidade de patches e orientações de fornecedor"
          ],
          "limites": [
            "não informa procedimento de teste, janela operacional ou compatibilidade com sistemas críticos",
            "recomendação de alerta de segurança, não obrigação universal"
          ]
        },
        {
          "proposicao": "Entre as medidas recomendadas estão minimizar a exposição de rede de dispositivos/sistemas de controle, evitar acessibilidade a partir da internet, posicionar redes de controle e dispositivos remotos atrás de firewalls, isolá-los da rede corporativa e usar acesso remoto seguro como VPN quando necessário.",
          "trechos": [
            "E17bd6f60d466f9f9:1390:2083"
          ],
          "condicoes": [
            "quando houver dispositivos de controle conectados em rede e necessidade de acesso remoto",
            "a segurança da VPN depende da atualização e segurança dos dispositivos conectados"
          ],
          "limites": [
            "o documento não define zonas, conduítes ou DMZ explicitamente",
            "as medidas são recomendações associadas a um alerta específico"
          ]
        }
      ]
    },
    {
      "id": "Ea3d79d3ac748d62d",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O escopo de IACS considerado pelo guia inclui sistemas básicos de controle de processo, funções de camada independente de proteção, sistemas de segurança, controle/aquisição de dados elétricos e sistemas de informação e de negócios associados conectados pela infraestrutura de rede do IACS.",
          "trechos": [
            "Ea3d79d3ac748d62d:0:700",
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "no escopo do guia de cibersegurança do HSE para instalações abrangidas"
          ],
          "limites": [
            "embora ajude a delimitar fronteiras IT/OT, o trecho não descreve segmentação por zonas e conduítes",
            "é definição adotada em guia regulatório estrangeiro"
          ]
        },
        {
          "proposicao": "Para offshore, o escopo pode incluir também sistemas marítimos, de perfuração e de monitoramento de movimento de helicóptero.",
          "trechos": [
            "Ea3d79d3ac748d62d:700:1390"
          ],
          "condicoes": [
            "apenas no contexto offshore indicado pelo guia"
          ],
          "limites": [
            "a ampliação de escopo não equivale a prescrever a mesma arquitetura de segmentação para todos esses sistemas",
            "o trecho não trata especificamente de FPSO"
          ]
        },
        {
          "proposicao": "Nas instalações reguladas por NIS, a autoavaliação baseada no CAF e o plano de melhoria decorrente são usados como ponto de partida para inspeções por amostragem dos objetivos, princípios e resultados esperados.",
          "trechos": [
            "Ea3d79d3ac748d62d:1390:2090",
            "Ea3d79d3ac748d62d:2090:2378"
          ],
          "condicoes": [
            "aplicável ao regime NIS mencionado e à submissão do plano à autoridade indicada"
          ],
          "limites": [
            "o trecho não apresenta critérios técnicos de inventário, DMZ, firewall ou menor privilégio",
            "processo regulatório estrangeiro, sem conversão automática em requisito local"
          ]
        }
      ]
    },
    {
